package com.bank.prices;

import io.grpc.*;
import java.util.logging.Logger;

// Logs every call's method, final status, and latency — zero changes to services.
public class LoggingInterceptor implements ServerInterceptor {
    private static final Logger log = Logger.getLogger(LoggingInterceptor.class.getName());

    @Override
    public <ReqT, RespT> ServerCall.Listener<ReqT> interceptCall(
            ServerCall<ReqT, RespT> call, Metadata headers, ServerCallHandler<ReqT, RespT> next) {
        long start = System.nanoTime();
        String method = call.getMethodDescriptor().getFullMethodName();
        log.info(() -> "gRPC START " + method);
        // wrap the call so we can observe the status when it closes
        ServerCall<ReqT, RespT> wrapped = new ForwardingServerCall.SimpleForwardingServerCall<>(call) {
            @Override
            public void close(Status status, Metadata trailers) {
                long ms = (System.nanoTime() - start) / 1_000_000;
                log.info(() -> "gRPC END   " + method + " status=" + status.getCode() + " " + ms + "ms");
                super.close(status, trailers);
            }
        };
        return next.startCall(wrapped, headers);
    }
}
