package com.bank.prices;

import io.grpc.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

// Simple per-client token bucket: reject excess calls with RESOURCE_EXHAUSTED.
public class RateLimiterInterceptor implements ServerInterceptor {
    private static final Logger log = Logger.getLogger(RateLimiterInterceptor.class.getName());
    private static final int MAX_PER_WINDOW = 5;
    private final Map<String, AtomicInteger> counters = new ConcurrentHashMap<>();

    @Override
    public <ReqT, RespT> ServerCall.Listener<ReqT> interceptCall(
            ServerCall<ReqT, RespT> call, Metadata headers, ServerCallHandler<ReqT, RespT> next) {
        String client = String.valueOf(call.getAttributes()
            .get(Grpc.TRANSPORT_ATTR_REMOTE_ADDR));
        int used = counters.computeIfAbsent(client, k -> new AtomicInteger()).incrementAndGet();
        if (used > MAX_PER_WINDOW) {
            log.warning(() -> "Rate limit exceeded for " + client);
            call.close(Status.RESOURCE_EXHAUSTED.withDescription("too many requests"), new Metadata());
            return new ServerCall.Listener<>() { };
        }
        return next.startCall(call, headers);
    }
}
