package com.bank.prices;

import com.bank.prices.gen.*;
import io.grpc.stub.ServerCallStreamObserver;
import io.grpc.stub.StreamObserver;
import java.math.BigDecimal;
import java.util.Set;
import java.util.concurrent.*;
import java.util.logging.Logger;

public class PriceStreamServiceImpl extends PriceStreamServiceGrpc.PriceStreamServiceImplBase {
    private static final Logger log = Logger.getLogger(PriceStreamServiceImpl.class.getName());
    private final ScheduledExecutorService ticker = Executors.newSingleThreadScheduledExecutor();

    @Override
    public StreamObserver<PriceRequest> streamPrices(StreamObserver<PriceUpdate> responseObs) {
        Set<String> subscribed = ConcurrentHashMap.newKeySet();
        ServerCallStreamObserver<PriceUpdate> sco = (ServerCallStreamObserver<PriceUpdate>) responseObs;

        // server pushes a fresh price for each subscribed symbol every second
        ScheduledFuture<?> task = ticker.scheduleAtFixedRate(() -> {
            if (!sco.isReady()) return;    // respect flow control (backpressure)
            for (String sym : subscribed) {
                BigDecimal price = new BigDecimal(2400 + Math.round(Math.random() * 100));
                responseObs.onNext(PriceUpdate.newBuilder()
                    .setSymbol(sym).setPrice(price.toString())
                    .setTs(System.currentTimeMillis()).build());
            }
        }, 0, 1, TimeUnit.SECONDS);

        // inbound: trader keeps adding/removing symbols on the SAME stream
        return new StreamObserver<>() {
            @Override public void onNext(PriceRequest req) {
                if ("SUBSCRIBE".equals(req.getAction())) {
                    subscribed.add(req.getSymbol());
                    log.info(() -> "SUBSCRIBE " + req.getSymbol());
                } else {
                    subscribed.remove(req.getSymbol());
                    log.info(() -> "UNSUBSCRIBE " + req.getSymbol());
                }
            }
            @Override public void onError(Throwable t) {
                log.severe("client stream error: " + t.getMessage());
                task.cancel(true);                // stop ticker on disconnect (no leak)
            }
            @Override public void onCompleted() {
                task.cancel(true);
                responseObs.onCompleted();        // close the server→client direction
            }
        };
    }
}
