package com.bank.prices;

import io.grpc.*;
import java.util.logging.Logger;

public class PriceServer {
    private static final Logger log = Logger.getLogger(PriceServer.class.getName());

    public static void main(String[] args) throws Exception {
        Server server = ServerBuilder.forPort(9090)
            .addService(ServerInterceptors.intercept(new PriceStreamServiceImpl(),
                new LoggingInterceptor(), new RateLimiterInterceptor()))   // interceptor chain
            .build().start();
        log.info("Live price gRPC server on 9090");
        server.awaitTermination();
    }
}
