package com.bank.prices;

import com.bank.prices.gen.*;
import io.grpc.*;
import io.grpc.stub.StreamObserver;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

public class PriceClient {
    private static final Logger log = Logger.getLogger(PriceClient.class.getName());

    public static void main(String[] args) throws Exception {
        ManagedChannel channel = ManagedChannelBuilder
            .forAddress("localhost", 9090).usePlaintext().build();
        PriceStreamServiceGrpc.PriceStreamServiceStub stub =
            PriceStreamServiceGrpc.newStub(channel);          // async stub for streaming
        CountDownLatch done = new CountDownLatch(1);

        StreamObserver<PriceRequest> requestObs = stub.streamPrices(new StreamObserver<>() {
            @Override public void onNext(PriceUpdate u) {
                log.info(() -> u.getSymbol() + " = Rs." + u.getPrice());
            }
            @Override public void onError(Throwable t) { done.countDown(); }
            @Override public void onCompleted() { done.countDown(); }
        });

        // trader subscribes to two symbols on the same bidi stream
        requestObs.onNext(PriceRequest.newBuilder().setSymbol("RELIANCE").setAction("SUBSCRIBE").build());
        requestObs.onNext(PriceRequest.newBuilder().setSymbol("TCS").setAction("SUBSCRIBE").build());
        Thread.sleep(3000);
        requestObs.onCompleted();                              // trader hangs up
        done.await(5, TimeUnit.SECONDS);
        channel.shutdown();
    }
}
